import{c as e,d as t,f as n,l as r,p as i,s as a,u as o}from"./index-CHK1GsUg.js";function s(e){let t=e.replace(/([a-z0-9])([A-Z])/g,`$1 $2`).replace(/([A-Z]+)([A-Z][a-z])/g,`$1 $2`).trim().split(/\s+/).map(e=>e===e.toUpperCase()&&/[A-Z]/.test(e)?e:e.toLowerCase()).join(` `);return t.charAt(0).toUpperCase()+t.slice(1)}function c(e,t,n,r,i){let o=a(e,t,n,`rdfs:label`,i.label??s(r),`en`);for(let[e,r]of[[`skos:definition`,i.definition],[`rdfs:comment`,i.comment],[`skos:example`,i.example]])r&&(o=a(o,t,n,e,r,`en`));return o}function l(s){let l=i(s.iri,s.prefix);for(let[e,t,n]of s.metadata??[])l=a(l,`ontology`,``,e,t,n);let u=new Map;for(let e of s.classes){let t=r(l,{localName:e.name,position:{x:e.at[0],y:e.at[1]}});l=t.ontology,u.set(e.name,t.id)}for(let e of s.classes){let n=u.get(e.name),r=e.parent?u.get(e.parent):void 0;n&&r&&(l=t(l,n,r))}for(let t of s.classes){let n=u.get(t.name);if(n){l=c(l,`class`,n,t.name,t);for(let[e,r]of t.labels??[])l=a(l,`class`,n,`skos:prefLabel`,e,r);for(let r of t.attributes??[]){let t=e(l,{classId:n,localName:r.name,range:r.range});l=c(t.ontology,`attribute`,t.propertyId,r.name,r)}}}let d=new Map;for(let e of s.relations){let t=d.get(e.name);if(!t){let n=o(l,{localName:e.name});l=n.ontology,t=n.id,d.set(e.name,t),l=c(l,`relation`,t,e.name,e)}let r=u.get(e.from),i=u.get(e.to);r&&i&&(l=n(l,{propertyId:t,subjectClassId:r,objectClassId:i}).ontology)}for(let e of s.spareProperties??[]){let t=o(l,{localName:e.name});l=c(t.ontology,`relation`,t.id,e.name,e)}return l}function u(e){return{...e,build:()=>l(e)}}function d(e){return{classes:e.classes.length,relations:new Set(e.relations.map(e=>e.name)).size+(e.spareProperties?.length??0),attributes:e.classes.reduce((e,t)=>e+(t.attributes?.length??0),0)}}var f=u({key:`automotive`,title:`Vehicle dealership`,summary:`Vehicles, the firms that build and sell them, and the sales, servicing and warranties that follow. Shows a branching taxonomy and a relation reused across three classes.`,iri:`https://example.org/automotive/`,prefix:`auto`,metadata:[[`dcterms:title`,`Automotive Sales and Service`,`en`],[`dcterms:description`,`A schema covering vehicles, the organisations that manufacture, sell and service them, and the transactions between them.`,`en`],[`dcterms:creator`,`OntoSchema examples`],[`dcterms:license`,`https://creativecommons.org/licenses/by/4.0/`],[`owl:versionInfo`,`1.0.0`]],classes:[{name:`Vehicle`,at:[40,40],definition:`A powered road vehicle offered for sale or service.`,comment:`The individual vehicle, identified by its VIN — not the model. Two identical cars on the forecourt are two vehicles.`,example:`The blue estate with 42,000 miles on it.`,labels:[[`Vehicle`,`en`],[`Voertuig`,`nl`],[`Fahrzeug`,`de`]],attributes:[{name:`vin`,range:`string`,label:`VIN`,definition:`The seventeen-character Vehicle Identification Number.`,comment:`The only truly unique identifier here, and the one a registration can outlive.`,example:`WVWZZZ1JZXW000001`},{name:`make`,range:`string`,definition:`The marque the vehicle is sold under.`,comment:`Held as text as well as through manufacturedBy, because the marque and the company that owns it often differ.`,example:`Volkswagen`},{name:`model`,range:`string`,definition:`The model name given by the manufacturer.`,comment:`A name, not a class: modelling every model would double the size of this schema.`,example:`Golf`},{name:`modelYear`,range:`integer`,definition:`The model year the vehicle belongs to.`,comment:`Not the year it was built: manufacturers run model years ahead of the calendar.`,example:`2019`},{name:`colour`,range:`string`,definition:`The colour of the bodywork as sold.`,comment:`The manufacturer's name for it, which is why this is text and not a code.`,example:`Deep Black Pearl`},{name:`mileage`,range:`integer`,definition:`Distance travelled, as shown on the odometer.`,comment:`A figure at a moment in time. The reading at each service is kept on ServiceRecord instead.`,example:`42000`},{name:`listPrice`,range:`decimal`,definition:`The asking price before any negotiation.`,comment:`What was asked, not what was paid — the price agreed lives on SalesTransaction.`,example:`18995.00`},{name:`firstRegistered`,range:`date`,definition:`The day the vehicle was first put on the road.`,comment:`What a vehicle age is measured from, rather than the model year.`,example:`2019-03-01`}]},{name:`Car`,parent:`Vehicle`,at:[40,340],definition:`A vehicle built to carry people rather than goods.`,comment:`Carries only what a truck and a motorcycle have no use for.`,example:`A five-door hatchback.`,labels:[[`Car`,`en`],[`Auto`,`nl`]],attributes:[{name:`doorCount`,range:`integer`,definition:`How many doors the car has.`,comment:`Counted the way the trade counts them, so a hatchback tailgate is a door.`,example:`5`},{name:`seatCount`,range:`integer`,definition:`How many people the car is built to carry.`,comment:`As approved, including the driver.`,example:`5`},{name:`bodyStyle`,range:`string`,definition:`The shape of the body.`,comment:`Text rather than a fixed list, because the trade keeps inventing new ones.`,example:`Estate`}]},{name:`Truck`,parent:`Vehicle`,at:[320,340],definition:`A goods vehicle built to carry a load.`,comment:`Split from Car by what it is for, which is what its own attributes are about.`,example:`A two-axle flatbed.`,attributes:[{name:`payloadKg`,range:`integer`,label:`Payload (kg)`,definition:`The greatest load the truck may legally carry.`,comment:`The load, not the total weight of the vehicle with it.`,example:`1200`},{name:`axleCount`,range:`integer`,definition:`How many axles the truck runs on.`,comment:`What most road tolls and weight limits are set by.`,example:`2`}]},{name:`Motorcycle`,parent:`Vehicle`,at:[600,340],definition:`A two-wheeled motor vehicle.`,comment:`The third branch, present to make offeredBy span three classes rather than two.`,example:`A 650cc touring bike.`,attributes:[{name:`hasSidecar`,range:`boolean`,definition:`Whether a sidecar is fitted.`,comment:`Changes the licence needed to ride it, which is why it is recorded at all.`,example:`false`}]},{name:`Engine`,at:[880,40],definition:`The power unit fitted to a vehicle.`,comment:`A class of its own because an engine is replaced, recalled and specified separately from the vehicle around it.`,example:`A 2.0-litre diesel.`,attributes:[{name:`engineCode`,range:`string`,definition:`The manufacturer's identifier for this engine design.`,comment:`Identifies the design, not the individual unit, which is what parts are ordered against.`,example:`CRBC`},{name:`displacementLitres`,range:`decimal`,label:`Displacement (litres)`,definition:`Swept volume of the cylinders.`,comment:`Decimal because engines are spoken about in tenths of a litre.`,example:`2.0`},{name:`horsepower`,range:`integer`,definition:`Power output at the crankshaft.`,comment:`One figure, though which standard it was measured to varies by market.`,example:`150`},{name:`fuelType`,range:`string`,definition:`What the engine runs on.`,comment:`Text, so hybrids can be described without inventing a class for each combination.`,example:`Diesel`},{name:`isElectric`,range:`boolean`,definition:`Whether the unit is purely electric.`,comment:`A flag rather than a fuel type, because it changes what the other fields mean.`,example:`false`}]},{name:`Organisation`,at:[1160,40],definition:`A company taking part in the trade.`,comment:`Above the three roles below, so the facts every company has are stated once. A firm can play more than one role.`,example:`A registered company.`,attributes:[{name:`legalName`,range:`string`,definition:`The name the company is registered under.`,comment:`Kept apart from a trading name, which is what appears on the forecourt.`,example:`Northgate Motors Limited`},{name:`registrationNumber`,range:`string`,definition:`The identifier held by the company register.`,comment:`A string because it carries leading zeros and letters in most jurisdictions.`,example:`04512377`},{name:`website`,range:`anyURI`,definition:`The official site for the company.`,comment:`One address, the one the company controls.`,example:`https://example.org/northgate`},{name:`foundedOn`,range:`date`,definition:`The day the company was incorporated.`,comment:`Incorporation, which can be well after trading began.`,example:`2002-06-11`}]},{name:`Manufacturer`,parent:`Organisation`,at:[1160,340],definition:`An organisation that builds vehicles.`,comment:`A role, not a separate kind of company: a manufacturer may also run dealerships.`,example:`Volkswagen AG.`,attributes:[{name:`countryOfOrigin`,range:`string`,definition:`Where the manufacturer is based.`,comment:`Where the company is from, not where any given vehicle was assembled.`,example:`Germany`}]},{name:`Dealership`,parent:`Organisation`,at:[1440,340],definition:`An organisation that sells vehicles to the public.`,comment:`One site. A chain of showrooms is several dealerships under one company.`,example:`Northgate Motors, Leeds.`,labels:[[`Dealership`,`en`],[`Autodealer`,`nl`]],attributes:[{name:`tradingName`,range:`string`,definition:`The name the dealership trades under.`,comment:`What is on the sign, which is rarely the legal name.`,example:`Northgate Motors`},{name:`city`,range:`string`,definition:`Where the showroom is.`,comment:`A city rather than an address, which is what buyers search by.`,example:`Leeds`},{name:`isAuthorised`,range:`boolean`,definition:`Whether a manufacturer has franchised this dealership.`,comment:`What separates a franchised dealer from an independent one.`,example:`true`}]},{name:`ServiceCentre`,parent:`Organisation`,at:[1720,340],definition:`A workshop that services and repairs vehicles.`,comment:`Separate from a dealership because plenty of workshops sell nothing at all.`,example:`An independent garage.`,attributes:[{name:`bayCount`,range:`integer`,definition:`How many vehicles can be worked on at once.`,comment:`The usual measure of a workshop, and what its capacity is booked against.`,example:`6`},{name:`openedOn`,range:`date`,definition:`The day the workshop opened.`,comment:`The site opening, which may differ from the company being founded.`,example:`2011-09-05`}]},{name:`Person`,at:[40,640],definition:`A human taking part in the trade.`,comment:`Above customer and employee, because the same person is often both — the salesperson who buys a car.`,example:`Anyone in the address book.`,attributes:[{name:`fullName`,range:`string`,definition:`The name the person goes by.`,comment:`One field, deliberately: splitting names into given and family breaks outside a narrow set of conventions.`,example:`Aisha Rahman`},{name:`email`,range:`string`,definition:`An address to reach the person at.`,comment:`A string rather than a URI, because that is what people paste into a form.`,example:`aisha@example.org`},{name:`phone`,range:`string`,definition:`A number to reach the person on.`,comment:`A string, because a phone number has a leading zero and is never arithmetic.`,example:`+44 113 496 0000`},{name:`dateOfBirth`,range:`date`,definition:`The day the person was born.`,comment:`Held because finance and insurance need an age, not for its own sake.`,example:`1986-11-02`}]},{name:`Customer`,parent:`Person`,at:[40,940],definition:`Someone who buys or owns a vehicle.`,comment:`A role. Someone becomes a customer through a transaction, not by being a person.`,example:`The buyer on an invoice.`,attributes:[{name:`customerSince`,range:`date`,definition:`When this person first bought from the business.`,comment:`The first purchase, which is what loyalty is measured from.`,example:`2015-04-18`},{name:`loyaltyPoints`,range:`integer`,definition:`Points accrued on the loyalty scheme.`,comment:`A running total, so it says nothing about how it was reached.`,example:`1450`}]},{name:`Employee`,parent:`Person`,at:[320,940],definition:`Someone employed by an organisation in the trade.`,comment:`The other role a person can take, and the reason Person exists above both.`,example:`A salesperson or a technician.`,attributes:[{name:`staffNumber`,range:`string`,definition:`The identifier the employer uses.`,comment:`Unique within one employer, which is why it is not an identifier for the person.`,example:`NG-0142`},{name:`jobTitle`,range:`string`,definition:`What the employee does.`,comment:`Text, not a role class: job titles are invented faster than they can be modelled.`,example:`Senior Technician`},{name:`hiredOn`,range:`date`,definition:`The day the employment began.`,comment:`The current employment; a work history is out of scope here.`,example:`2018-02-19`}]},{name:`SalesTransaction`,at:[640,640],definition:`The sale of one vehicle to one customer.`,comment:`The event, which is what makes a person a customer and a vehicle sold. Everything about the sale that the vehicle itself should not carry lives here.`,example:`Invoice NG-2024-0088.`,attributes:[{name:`invoiceNumber`,range:`string`,definition:`The identifier on the paperwork.`,comment:`The reference a customer will quote, so it has to survive as written.`,example:`NG-2024-0088`},{name:`soldOn`,range:`date`,definition:`The day the sale completed.`,comment:`Completion, not the day a deposit was taken.`,example:`2024-05-02`},{name:`salePrice`,range:`decimal`,definition:`What the customer actually paid.`,comment:`The agreed figure, which is why the vehicle keeps its asking price separately.`,example:`17250.00`},{name:`discount`,range:`decimal`,definition:`How much came off the asking price.`,comment:`Recorded rather than derived, because a part-exchange muddies the subtraction.`,example:`1745.00`},{name:`paymentMethod`,range:`string`,definition:`How the sale was paid for.`,comment:`Text, so finance arrangements can be described without a class for each.`,example:`Hire purchase`}]},{name:`ServiceRecord`,at:[1e3,640],definition:`One visit of a vehicle to a service centre.`,comment:`One visit, so a vehicle history is the set of them rather than a field on the vehicle.`,example:`The 40,000-mile service.`,attributes:[{name:`servicedOn`,range:`date`,definition:`The day the work was done.`,comment:`When the work happened, not when it was booked or invoiced.`,example:`2023-11-20`},{name:`odometerReading`,range:`integer`,definition:`What the odometer showed at the visit.`,comment:`A reading at a point in time, which is what makes a service history evidence rather than a claim.`,example:`39880`},{name:`workDescription`,range:`string`,definition:`An account of the work carried out at this visit.`,comment:`Free prose, because this is what the customer reads on the invoice.`,example:`Oil and filter change, front brake pads replaced.`},{name:`labourHours`,range:`decimal`,definition:`Time booked to the job.`,comment:`Decimal because labour is billed in fractions of an hour.`,example:`2.5`},{name:`totalCost`,range:`decimal`,definition:`What the visit cost the customer.`,comment:`Parts and labour together; splitting them needs a line-item class.`,example:`412.60`}]},{name:`Warranty`,at:[1360,640],definition:`A guarantee covering a vehicle for a period or a distance.`,comment:`Attached to the vehicle rather than the buyer, which is what makes it transferable.`,example:`Three years or 60,000km.`,attributes:[{name:`policyNumber`,range:`string`,definition:`The identifier of the guarantee.`,comment:`What a claim is made against.`,example:`WTY-99120`},{name:`startsOn`,range:`date`,definition:`The day cover begins.`,comment:`Usually first registration, but not always, which is why it is stated.`,example:`2019-03-01`},{name:`endsOn`,range:`date`,definition:`The day cover ends.`,comment:`Whichever comes first, this or the distance limit — nothing here enforces that.`,example:`2022-03-01`},{name:`coverageKm`,range:`integer`,label:`Coverage (km)`,definition:`The distance the cover lasts for.`,comment:`The other half of the limit, and the reason the end date alone is not enough.`,example:`60000`},{name:`isTransferable`,range:`boolean`,definition:`Whether the cover passes to a new owner.`,comment:`What makes a warranty worth something at resale.`,example:`true`}]}],relations:[{name:`manufacturedBy`,from:`Vehicle`,to:`Manufacturer`,definition:`The organisation that built the vehicle.`,comment:`The builder, which for a badge-engineered car is not always the marque on the boot.`,example:`A Golf is manufacturedBy Volkswagen AG.`},{name:`hasEngine`,from:`Vehicle`,to:`Engine`,definition:`The power unit fitted to this vehicle.`,comment:`Fitted now, so replacing an engine changes what this points at.`,example:`The blue estate hasEngine the 2.0-litre diesel.`},{name:`offeredBy`,from:`Car`,to:`Dealership`,definition:`A dealership offering this kind of vehicle for sale.`,comment:`Drawn from all three vehicle kinds, which is what makes it worth looking at: RDFS can no longer state one rdfs:domain, while each class keeps a SHACL shape of its own. The Export tab shows both.`,example:`A Golf is offeredBy Northgate Motors.`},{name:`offeredBy`,from:`Truck`,to:`Dealership`},{name:`offeredBy`,from:`Motorcycle`,to:`Dealership`},{name:`involvesVehicle`,from:`SalesTransaction`,to:`Vehicle`,definition:`The vehicle that changed hands.`,comment:`One vehicle per sale; a part-exchange is two transactions, not one with two.`,example:`Invoice NG-2024-0088 involvesVehicle the blue estate.`},{name:`soldTo`,from:`SalesTransaction`,to:`Customer`,definition:`The customer who bought.`,comment:`The buyer on the paperwork, who need not be the person who ends up driving it.`,example:`Invoice NG-2024-0088 soldTo Aisha Rahman.`},{name:`soldBy`,from:`SalesTransaction`,to:`Employee`,definition:`The employee who handled the sale.`,comment:`Who gets the commission, which is why it is the employee and not the dealership.`,example:`Invoice NG-2024-0088 soldBy staff NG-0142.`},{name:`servicedAt`,from:`Vehicle`,to:`ServiceCentre`,definition:`A workshop this vehicle is serviced at.`,comment:`The standing arrangement; each individual visit is a ServiceRecord.`,example:`The blue estate is servicedAt Northgate Workshop.`},{name:`hasServiceRecord`,from:`Vehicle`,to:`ServiceRecord`,definition:`A visit in this vehicle history.`,comment:`Many per vehicle, which together are what a buyer means by service history.`,example:`The blue estate hasServiceRecord the 40,000-mile service.`},{name:`performedBy`,from:`ServiceRecord`,to:`Employee`,definition:`The technician who did the work.`,comment:`The person, so work can be traced back through a recall.`,example:`The 40,000-mile service was performedBy staff NG-0142.`},{name:`coveredBy`,from:`Vehicle`,to:`Warranty`,definition:`A guarantee that covers this vehicle.`,comment:`More than one is normal: a manufacturer warranty and a paint warranty can overlap.`,example:`The blue estate is coveredBy WTY-99120.`},{name:`issuedBy`,from:`Warranty`,to:`Manufacturer`,definition:`Who stands behind the guarantee.`,comment:`The manufacturer here; a dealer-issued warranty would need the range widening.`,example:`WTY-99120 was issuedBy Volkswagen AG.`},{name:`employedBy`,from:`Employee`,to:`Organisation`,definition:`The organisation the employee works for.`,comment:`Points at Organisation, not at Dealership, so workshop staff fit the same relation.`,example:`Staff NG-0142 is employedBy Northgate Motors Limited.`},{name:`ownedBy`,from:`Vehicle`,to:`Customer`,definition:`Who currently owns the vehicle.`,comment:`The current keeper only. A chain of past owners would need a class holding the dates.`,example:`The blue estate is ownedBy Aisha Rahman.`}],spareProperties:[{name:`tradedInAgainst`,definition:`A vehicle given in part-exchange against another purchase.`,comment:`Declared but never drawn, so it sits unused in the property list. Draw it between two classes to put it on the canvas.`,example:`The old hatchback was tradedInAgainst the blue estate.`}]}),p=u({key:`university`,title:`University`,summary:`Students, staff, courses and the terms they run in. Shows the catalogue-versus-offering distinction, a self-referencing prerequisite relation, and a relation reused for two kinds of membership.`,iri:`https://example.org/university/`,prefix:`uni`,metadata:[[`dcterms:title`,`University Teaching and Research`,`en`],[`dcterms:description`,`A schema covering academic organisation, the teaching catalogue, enrolment and research output.`,`en`],[`dcterms:creator`,`OntoSchema examples`],[`owl:versionInfo`,`1.0.0`]],classes:[{name:`Person`,at:[40,40],definition:`Anyone the university keeps a record of.`,comment:`Above student and instructor, because the same person is often both — a doctoral student who teaches.`,example:`Anyone with a university account.`,attributes:[{name:`fullName`,range:`string`,definition:`The name the person goes by.`,comment:`One field on purpose: splitting a name into given and family assumes a convention many people do not follow.`,example:`Wei Chen`},{name:`email`,range:`string`,definition:`The university address for this person.`,comment:`The institutional address, which is what accounts are keyed on.`,example:`w.chen@example.org`},{name:`dateOfBirth`,range:`date`,definition:`The day the person was born.`,comment:`Kept for registry purposes only, and one of the few fields here that is personal.`,example:`1998-07-30`},{name:`orcid`,range:`anyURI`,label:`ORCID`,definition:`The persistent researcher identifier for this person.`,comment:`A URI rather than a bare code, because that is the form that resolves and survives a name change.`,example:`https://orcid.org/0000-0002-1825-0097`}]},{name:`Student`,parent:`Person`,at:[40,340],definition:`A person admitted to a programme of study.`,comment:`A role rather than a kind of person, which is why it sits under Person.`,example:`A second-year undergraduate.`,attributes:[{name:`studentNumber`,range:`string`,definition:`The registry identifier for this student.`,comment:`A string because it carries leading zeros and is never arithmetic.`,example:`20194471`},{name:`startedOn`,range:`date`,definition:`The day the student first registered.`,comment:`First registration, which survives a change of programme.`,example:`2022-09-26`},{name:`isInternational`,range:`boolean`,definition:`Whether the student is classed as international for fees.`,comment:`A fee status, not a nationality: the two come apart often.`,example:`true`}]},{name:`Instructor`,parent:`Person`,at:[320,340],definition:`A member of academic staff who teaches.`,comment:`The teaching role. Research-only staff would need a sibling class or a wider one.`,example:`A senior lecturer.`,attributes:[{name:`staffNumber`,range:`string`,definition:`The payroll identifier for this member of staff.`,comment:`Separate from a student number, which the same person may also hold.`,example:`S-40118`},{name:`academicTitle`,range:`string`,definition:`The rank the post carries.`,comment:`Text, because the ladder differs between countries and even between faculties.`,example:`Senior Lecturer`},{name:`appointedOn`,range:`date`,definition:`The day the appointment began.`,comment:`The current post, so a promotion within the university does not reset it.`,example:`2016-01-04`}]},{name:`Faculty`,at:[640,40],definition:`A top-level academic division of the university.`,comment:`The widest unit here; anything above it is the university itself, which is not modelled.`,example:`The Faculty of Science.`,attributes:[{name:`facultyName`,range:`string`,definition:`What the division is called.`,comment:`The public name, which is what appears on a degree certificate.`,example:`Faculty of Science`},{name:`deanName`,range:`string`,definition:`Who currently leads the faculty.`,comment:`Text rather than a link to Person, which is the shortcut this example takes; a real registry would point at the person.`,example:`Prof. Wei Chen`}]},{name:`Department`,at:[640,340],definition:`An academic unit within a faculty.`,comment:`Where teaching and research actually sit, which is why programmes hang off it.`,example:`The Department of Computer Science.`,attributes:[{name:`departmentName`,range:`string`,definition:`What the unit is called.`,comment:`The name in the prospectus.`,example:`Computer Science`},{name:`departmentCode`,range:`string`,definition:`The short code used in course codes and timetables.`,comment:`What the first letters of a course code come from.`,example:`CS`},{name:`budget`,range:`decimal`,definition:`The annual budget allocated to the unit.`,comment:`Decimal so money is not rounded; the currency is left out, as elsewhere here.`,example:`4250000.00`}]},{name:`ResearchGroup`,at:[640,640],definition:`A group of staff working on a shared research theme.`,comment:`Sits under a department through the same partOf relation as a department under a faculty, which is why that property is drawn twice.`,example:`The Programming Languages group.`,attributes:[{name:`groupName`,range:`string`,definition:`What the group calls itself.`,comment:`Chosen by the group, so it has none of the formality of a department name.`,example:`Programming Languages`},{name:`researchTheme`,range:`string`,definition:`What the group works on.`,comment:`A sentence rather than a subject classification, which nobody agrees on anyway.`,example:`Type systems and program verification`},{name:`foundedOn`,range:`date`,definition:`The day the group was formed.`,comment:`Formation, which for most groups is when it was first funded.`,example:`2014-10-01`}]},{name:`Programme`,at:[960,40],definition:`A named qualification a student is admitted to.`,comment:`What a student is admitted to, as against a course, which they merely take.`,example:`BSc Computer Science.`,attributes:[{name:`programmeName`,range:`string`,definition:`What the qualification is called.`,comment:`The name as advertised and as printed on the certificate.`,example:`Computer Science`},{name:`award`,range:`string`,definition:`The qualification granted on completion.`,comment:`Held apart from the name, so BSc and MSc versions can share one.`,example:`BSc (Hons)`},{name:`durationYears`,range:`integer`,definition:`How long the programme takes full time.`,comment:`The full-time length; part-time study stretches it without changing this.`,example:`3`},{name:`totalCredits`,range:`integer`,definition:`Credits needed to complete the programme.`,comment:`What the credits on each course have to add up to.`,example:`360`}]},{name:`Course`,at:[960,340],definition:`A unit of teaching as it appears in the catalogue.`,comment:`The catalogue entry, which exists whether or not it runs this year. Anything that varies by term belongs on CourseOffering — the distinction this example is built around.`,example:`CS2010 Algorithms.`,attributes:[{name:`courseCode`,range:`string`,definition:`The catalogue identifier for the course.`,comment:`Stable across years, which is what makes a transcript readable a decade later.`,example:`CS2010`},{name:`courseTitle`,range:`string`,definition:`What the course is called.`,comment:`The catalogue title, which changes far less often than the syllabus.`,example:`Algorithms and Data Structures`},{name:`credits`,range:`integer`,definition:`Credit awarded for passing the course.`,comment:`A property of the course, not of any one running of it.`,example:`20`},{name:`level`,range:`integer`,definition:`The year of study the course is pitched at.`,comment:`A number so courses can be sorted; what each level means is institutional.`,example:`2`},{name:`syllabus`,range:`string`,definition:`What the course covers.`,comment:`The catalogue description; the week-by-week plan belongs to an offering.`,example:`Sorting, searching, graph traversal and complexity analysis.`}]},{name:`CourseOffering`,at:[1280,340],definition:`One running of a course in one term, with its own timetable and staff.`,comment:`The other half of the distinction. Students enrol in an offering, not a course: a room, a capacity and a set of dates only make sense here.`,example:`CS2010 in autumn 2024.`,attributes:[{name:`term`,range:`string`,definition:`The part of the year this offering runs in.`,comment:`Text, because terms, semesters and trimesters do not share a scheme.`,example:`Autumn`},{name:`academicYear`,range:`string`,definition:`The academic year this offering belongs to.`,comment:`A string because an academic year spans two calendar years.`,example:`2024/25`},{name:`capacity`,range:`integer`,definition:`How many students may enrol.`,comment:`Set per offering, usually by the room, which is why it is not on the course.`,example:`120`},{name:`startsOn`,range:`date`,definition:`The first day of teaching.`,comment:`Teaching, not registration, which opens well before.`,example:`2024-09-30`},{name:`endsOn`,range:`date`,definition:`The last day of teaching.`,comment:`The end of teaching; assessment usually runs past it.`,example:`2024-12-13`}]},{name:`Enrolment`,at:[1280,640],definition:`One student taking one offering, and how they did on it.`,comment:`A class rather than a relation, because the result belongs to neither the student nor the offering alone. The same shape as RecipeIngredient in the recipes example.`,example:`Wei Chen on CS2010, autumn 2024.`,attributes:[{name:`enrolledOn`,range:`date`,definition:`The day the student registered for the offering.`,comment:`Registration for this offering, not admission to the programme.`,example:`2024-09-16`},{name:`mark`,range:`decimal`,definition:`The numeric result the student was awarded.`,comment:`Decimal because marks are often carried to one place before being rounded.`,example:`72.5`},{name:`grade`,range:`string`,definition:`The result on the letter or class scale.`,comment:`Held beside the mark rather than derived, because the boundaries move.`,example:`A`},{name:`hasPassed`,range:`boolean`,definition:`Whether the student passed.`,comment:`Stated rather than worked out from the mark, which compensation rules complicate.`,example:`true`}]},{name:`Assessment`,at:[1600,340],definition:`A piece of assessed work set on an offering.`,comment:`Attached to the offering, so a coursework deadline can move between years.`,example:`The autumn 2024 coursework.`,attributes:[{name:`assessmentTitle`,range:`string`,definition:`What the piece of work is called.`,comment:`What appears on the deadline list students actually read.`,example:`Graph algorithms coursework`},{name:`assessmentType`,range:`string`,definition:`What kind of assessment it is.`,comment:`Text rather than a class, which keeps the example from sprouting a vocabulary.`,example:`Coursework`},{name:`weighting`,range:`decimal`,definition:`What share of the course mark this carries.`,comment:`A proportion; the weightings on one offering should total one.`,example:`0.4`},{name:`dueOn`,range:`dateTime`,definition:`When the work must be submitted.`,comment:`A time as well as a date, because a deadline is an hour and lateness is minutes.`,example:`2024-11-22T16:00:00`}]},{name:`Building`,at:[40,640],definition:`A building on campus.`,comment:`Present so rooms have somewhere to be, and so accessibility can be asked about.`,example:`The Cockcroft Building.`,attributes:[{name:`buildingName`,range:`string`,definition:`What the building is called.`,comment:`The name on the signage and the campus map.`,example:`Cockcroft Building`},{name:`address`,range:`string`,definition:`Where the building is.`,comment:`A full address, unlike the city-only fields elsewhere: people have to find it.`,example:`14 Mill Lane, Leeds`},{name:`hasStepFreeAccess`,range:`boolean`,definition:`Whether the building can be entered and used without steps.`,comment:`On the building rather than the room, which is where it is first decided.`,example:`true`}]},{name:`Room`,at:[320,640],definition:`A room on campus that teaching is timetabled into.`,comment:`Only teaching space. Offices and labs would widen this beyond what the example needs.`,example:`Lecture theatre 1.02.`,attributes:[{name:`roomNumber`,range:`string`,definition:`How the room is identified within its building.`,comment:`A string, because room numbers carry letters and dots.`,example:`1.02`},{name:`seats`,range:`integer`,definition:`How many people the room holds.`,comment:`What an offering capacity is usually set from.`,example:`150`},{name:`floor`,range:`integer`,definition:`Which floor the room is on.`,comment:`Ground floor is zero here, which is a convention worth stating.`,example:`1`}]},{name:`Publication`,at:[960,640],definition:`A piece of published research produced by people here.`,comment:`Points at Person rather than Instructor, so students and external co-authors fit.`,example:`A conference paper.`,attributes:[{name:`publicationTitle`,range:`string`,definition:`The title of the work.`,comment:`As published, which is what a citation has to match.`,example:`A verified compiler for a subset of ML`},{name:`doi`,range:`anyURI`,label:`DOI`,definition:`The Digital Object Identifier for the work.`,comment:`A URI, so it resolves; the bare code form would not.`,example:`https://doi.org/10.1000/182`},{name:`publishedOn`,range:`date`,definition:`The day the work was published.`,comment:`Publication, which can be long after acceptance.`,example:`2023-06-14`},{name:`venue`,range:`string`,definition:`The journal or conference it appeared in.`,comment:`Text rather than a class, which a bibliographic model would not accept.`,example:`ICFP 2023`},{name:`citationCount`,range:`integer`,definition:`How many other works cite this one.`,comment:`A figure at a moment in time, and only ever as good as its source.`,example:`37`}]}],relations:[{name:`partOf`,from:`Department`,to:`Faculty`,definition:`The larger academic unit this one belongs to.`,comment:`Drawn twice — department under faculty, research group under department — so one property serves both kinds of membership rather than two nearly identical ones.`,example:`Computer Science is partOf the Faculty of Science.`},{name:`partOf`,from:`ResearchGroup`,to:`Department`},{name:`offers`,from:`Department`,to:`Programme`,definition:`A qualification this department runs.`,comment:`Jointly run programmes would need this drawn from more than one department.`,example:`Computer Science offers BSc Computer Science.`},{name:`includesCourse`,from:`Programme`,to:`Course`,definition:`A course that counts towards this programme.`,comment:`Whether the course is compulsory or optional is not captured, which would need a class between the two.`,example:`BSc Computer Science includesCourse CS2010.`},{name:`hasOffering`,from:`Course`,to:`CourseOffering`,definition:`One running of this course.`,comment:`The link that carries the catalogue-versus-offering distinction.`,example:`CS2010 hasOffering CS2010 in autumn 2024.`},{name:`prerequisiteOf`,from:`Course`,to:`Course`,definition:`A course that must be passed before this one may be taken.`,comment:`From a class to itself, which is legal and worth seeing drawn. It points one way, so the graph of prerequisites cannot close a loop by accident.`,example:`CS1010 is a prerequisiteOf CS2010.`},{name:`taughtBy`,from:`CourseOffering`,to:`Instructor`,definition:`A member of staff teaching this offering.`,comment:`On the offering, so who teaches a course can change from year to year.`,example:`CS2010 in autumn 2024 is taughtBy Wei Chen.`},{name:`heldIn`,from:`CourseOffering`,to:`Room`,definition:`Where this offering is taught.`,comment:`One room, which a course split across a lecture theatre and labs will defeat.`,example:`CS2010 in autumn 2024 is heldIn room 1.02.`},{name:`hasAssessment`,from:`CourseOffering`,to:`Assessment`,definition:`A piece of assessed work set on this offering.`,comment:`Per offering, so deadlines and weightings can change between years.`,example:`CS2010 in autumn 2024 hasAssessment the graph coursework.`},{name:`forOffering`,from:`Enrolment`,to:`CourseOffering`,definition:`The offering this enrolment is on.`,comment:`One half of the pairing Enrolment exists to hold.`,example:`Wei Chen's enrolment is forOffering CS2010 in autumn 2024.`},{name:`byStudent`,from:`Enrolment`,to:`Student`,definition:`The student this enrolment belongs to.`,comment:`The other half of the pairing, which together make the mark mean something.`,example:`The autumn CS2010 enrolment is byStudent Wei Chen.`},{name:`enrolledOnProgramme`,from:`Student`,to:`Programme`,definition:`The qualification this student is working towards.`,comment:`Admission to a programme, which is separate from taking any of its courses.`,example:`Wei Chen is enrolledOnProgramme BSc Computer Science.`},{name:`supervisedBy`,from:`Student`,to:`Instructor`,definition:`The member of staff responsible for this student.`,comment:`Covers both a personal tutor and a research supervisor, which are rarely distinguished.`,example:`Wei Chen is supervisedBy Dr Okonkwo.`},{name:`memberOf`,from:`Instructor`,to:`ResearchGroup`,definition:`A research group this member of staff belongs to.`,comment:`More than one is normal, and none of them is the primary group.`,example:`Dr Okonkwo is memberOf Programming Languages.`},{name:`authoredBy`,from:`Publication`,to:`Person`,definition:`Someone who wrote this work.`,comment:`Points at Person rather than Instructor, so students and outside collaborators fit. Author order is not captured.`,example:`The ML compiler paper is authoredBy Wei Chen.`},{name:`locatedIn`,from:`Room`,to:`Building`,definition:`The building this room is in.`,comment:`What makes a room number meaningful, since they repeat across buildings.`,example:`Room 1.02 is locatedIn the Cockcroft Building.`}]}),m=u({key:`insurance`,title:`Insurance firm`,summary:`Policies, the assets they cover and the claims made against them. Shows a Party abstraction over people and companies, and one relation whose range differs per policy type.`,iri:`https://example.org/insurance/`,prefix:`ins`,metadata:[[`dcterms:title`,`General Insurance`,`en`],[`dcterms:description`,`A schema covering policies, coverages, insured assets, claims and settlement.`,`en`],[`dcterms:creator`,`OntoSchema examples`],[`owl:versionInfo`,`1.0.0`]],classes:[{name:`Party`,at:[40,40],definition:`Any person or company the firm deals with.`,comment:`The standard move in this domain: a policy can be held by a person or a company, and putting Party above both means every relation is drawn once instead of twice.`,example:`A policyholder, a claimant or a payee.`,attributes:[{name:`partyReference`,range:`string`,definition:`The identifier the firm uses for this party.`,comment:`Issued by the firm, so it works whether the party is a person or a company.`,example:`P-0099412`},{name:`contactEmail`,range:`string`,definition:`Where to reach the party by email.`,comment:`One address, the one correspondence goes to.`,example:`j.okafor@example.org`},{name:`contactPhone`,range:`string`,definition:`Where to reach the party by telephone.`,comment:`A string, because a phone number keeps its leading zero and is never arithmetic.`,example:`+44 20 7946 0000`},{name:`addressLine`,range:`string`,definition:`The street part of the postal address.`,comment:`One line, which is the simplification: addresses that need several would break this.`,example:`14 Mill Lane`},{name:`postcode`,range:`string`,definition:`The postal code for the address.`,comment:`Held apart from the street, because underwriting prices risk by postcode.`,example:`LS1 4AB`}]},{name:`Person`,parent:`Party`,at:[40,380],definition:`An individual the firm deals with.`,comment:`Carries what only a human has, which is what keeps Party free of it.`,example:`A named policyholder.`,attributes:[{name:`fullName`,range:`string`,definition:`The name the person is known by.`,comment:`One field, so it does not assume a given-and-family convention.`,example:`Joy Okafor`},{name:`dateOfBirth`,range:`date`,definition:`The day the person was born.`,comment:`Central here rather than incidental: age is priced into almost every premium.`,example:`1979-04-22`},{name:`occupation`,range:`string`,definition:`What the person does for a living.`,comment:`Text, though underwriting really wants a classified list of occupations.`,example:`Structural engineer`}]},{name:`Organisation`,parent:`Party`,at:[320,380],definition:`A company or other legal entity.`,comment:`The other kind of party, and the reason Party exists above both.`,example:`A limited company insuring its premises.`,attributes:[{name:`legalName`,range:`string`,definition:`The name the entity is registered under.`,comment:`The registered name, which is what a contract has to be in.`,example:`Mill Lane Joinery Limited`},{name:`registrationNumber`,range:`string`,definition:`The identifier held by the company register.`,comment:`A string: leading zeros and letters are both normal.`,example:`07741122`},{name:`industry`,range:`string`,definition:`What line of business the entity is in.`,comment:`What commercial risk is priced from, and the reason it is recorded at all.`,example:`Carpentry and joinery`}]},{name:`Agent`,parent:`Person`,at:[40,700],definition:`A broker or adviser who sells policies.`,comment:`Under Person, so an agent is also a party and can hold a policy of their own without anything extra.`,example:`An appointed representative.`,attributes:[{name:`agentCode`,range:`string`,definition:`The identifier the firm uses for this agent.`,comment:`What commission is tracked against.`,example:`AG-2210`},{name:`commissionRate`,range:`decimal`,definition:`The share of premium the agent earns.`,comment:`A proportion, not a percentage figure, so no multiplying by a hundred.`,example:`0.075`},{name:`isAuthorised`,range:`boolean`,definition:`Whether the agent is currently permitted to sell.`,comment:`A regulatory status that can be withdrawn without the record going away.`,example:`true`}]},{name:`Policy`,at:[680,40],definition:`A contract of insurance between the firm and a party.`,comment:`Holds what every policy has. What differs by kind is on the three subclasses, and what a policy actually covers is on Coverage.`,example:`Policy MP-4471, running for a year.`,attributes:[{name:`policyNumber`,range:`string`,definition:`The identifier of the contract.`,comment:`What the customer quotes, so it has to survive exactly as issued.`,example:`MP-4471`},{name:`startsOn`,range:`date`,definition:`The day cover begins.`,comment:`Inception, which may be later than the day the policy was sold.`,example:`2024-06-01`},{name:`endsOn`,range:`date`,definition:`The day cover ends.`,comment:`The end of this term; renewal makes a new policy rather than moving this.`,example:`2025-05-31`},{name:`annualPremium`,range:`decimal`,definition:`What the policyholder pays for a year of cover.`,comment:`Decimal, so money is never rounded by the type it is stored in.`,example:`612.40`},{name:`excess`,range:`decimal`,definition:`What the policyholder pays towards any claim.`,comment:`The policy-wide figure; a coverage can set its own deductible, which overrides it.`,example:`250.00`},{name:`status`,range:`string`,definition:`Where the policy stands.`,comment:`Text rather than a class, which a real system would regret and then fix.`,example:`Active`},{name:`isAutoRenewing`,range:`boolean`,definition:`Whether cover continues automatically at the end of the term.`,comment:`Changes what the end date means, which is why it sits next to it.`,example:`true`}]},{name:`MotorPolicy`,parent:`Policy`,at:[680,380],definition:`Insurance for a vehicle.`,comment:`One of the three kinds whose insures relation points somewhere different.`,example:`Cover on a van.`,attributes:[{name:`noClaimsYears`,range:`integer`,definition:`Consecutive years the holder has claimed nothing.`,comment:`The single largest discount in motor insurance, which is why it is on the policy.`,example:`7`},{name:`annualMileageLimit`,range:`integer`,definition:`The distance the policy assumes will be driven.`,comment:`A condition of cover, not a measurement: exceeding it can void a claim.`,example:`12000`}]},{name:`HomePolicy`,parent:`Policy`,at:[960,380],definition:`Insurance for a dwelling and its contents.`,comment:`The second kind, and the one whose insures points at a Dwelling.`,example:`Buildings and contents cover on a terraced house.`,attributes:[{name:`contentsLimit`,range:`decimal`,definition:`The most the policy will pay for contents.`,comment:`Separate from the building, which is usually insured for its rebuild cost.`,example:`50000.00`},{name:`coversAccidentalDamage`,range:`boolean`,definition:`Whether damage caused by accident is included.`,comment:`Almost always an extra, which is why it is a flag rather than assumed.`,example:`false`}]},{name:`LifePolicy`,parent:`Policy`,at:[1240,380],definition:`Insurance paying out on death or terminal illness.`,comment:`The third kind, and the one that insures no asset at all — which is why insures is not drawn from it.`,example:`Twenty-year term cover.`,attributes:[{name:`sumAssured`,range:`decimal`,definition:`The amount paid out when the policy pays.`,comment:`Fixed at inception, unlike a claim on an asset, which is assessed.`,example:`250000.00`},{name:`termYears`,range:`integer`,definition:`How many years the cover runs for.`,comment:`Held as a length as well as dates, because that is how the product is sold.`,example:`20`}]},{name:`Coverage`,at:[680,700],definition:`One risk a policy covers, and to what limit.`,comment:`A class rather than fields on the policy, because a policy covers several risks and each has its own limit.`,example:`Theft cover up to £10,000.`,attributes:[{name:`coverageType`,range:`string`,definition:`What risk this covers.`,comment:`Text, though a real book of business would want a controlled list.`,example:`Theft`},{name:`limitAmount`,range:`decimal`,definition:`The most this cover will pay.`,comment:`Per risk, so it can be lower than the policy as a whole.`,example:`10000.00`},{name:`deductible`,range:`decimal`,definition:`What the holder pays towards a claim on this cover.`,comment:`Overrides the policy excess where the two disagree.`,example:`100.00`}]},{name:`InsuredAsset`,at:[1560,40],definition:`Something of value protected by a policy.`,comment:`Above vehicle and dwelling for the same reason Party is above person and company.`,example:`Anything with a value on the schedule.`,attributes:[{name:`assetReference`,range:`string`,definition:`The identifier the firm uses for this asset.`,comment:`The firm's own reference, which works before any registration is known.`,example:`A-77120`},{name:`estimatedValue`,range:`decimal`,definition:`What the asset is thought to be worth.`,comment:`An estimate, and the reason the date it was made is kept beside it.`,example:`18500.00`},{name:`valuedOn`,range:`date`,definition:`When the valuation was made.`,comment:`What makes the value interpretable; an old valuation is a known risk.`,example:`2024-05-14`}]},{name:`Vehicle`,parent:`InsuredAsset`,at:[1560,380],definition:`A road vehicle covered by a motor policy.`,comment:`What a motor policy points at, and one half of why insures has no single range.`,example:`A panel van.`,attributes:[{name:`vin`,range:`string`,label:`VIN`,definition:`The seventeen-character Vehicle Identification Number.`,comment:`The identifier that outlives a change of plate.`,example:`WVWZZZ1JZXW000001`},{name:`registrationPlate`,range:`string`,definition:`The number plate currently carried.`,comment:`Transferable and reassignable, which is why the VIN is kept as well.`,example:`LS19 KTP`},{name:`make`,range:`string`,definition:`The marque of the vehicle.`,comment:`One of the two figures that drive a motor premium, with the model.`,example:`Volkswagen`},{name:`model`,range:`string`,definition:`The model name of the vehicle.`,comment:`A name, not a class: modelling every model is a schema of its own.`,example:`Transporter`}]},{name:`Dwelling`,parent:`InsuredAsset`,at:[1840,380],definition:`A residential property covered by a home policy.`,comment:`What a home policy points at, and the other half of why insures has no single range.`,example:`A terraced house.`,attributes:[{name:`buildYear`,range:`integer`,definition:`The year the property was built.`,comment:`A year, because older records rarely offer better than that.`,example:`1904`},{name:`bedroomCount`,range:`integer`,definition:`How many bedrooms the property has.`,comment:`The usual proxy for size, and what contents cover is estimated from.`,example:`3`},{name:`isListedBuilding`,range:`boolean`,definition:`Whether the property is legally protected.`,comment:`Changes what a repair may cost enormously, which is why it is asked.`,example:`false`}]},{name:`Claim`,at:[1240,700],definition:`A request for payment under a policy.`,comment:`What was asked for. What the firm decided is on ClaimAssessment, deliberately apart.`,example:`A claim for storm damage.`,attributes:[{name:`claimNumber`,range:`string`,definition:`The identifier of the claim.`,comment:`What every letter about the claim will quote.`,example:`CL-2024-8812`},{name:`reportedOn`,range:`date`,definition:`The day the claim was made.`,comment:`Kept apart from the incident date, because the gap between them matters.`,example:`2024-08-19`},{name:`incidentOn`,range:`date`,definition:`The day the thing being claimed for happened.`,comment:`What decides whether the policy was in force at the time.`,example:`2024-08-16`},{name:`amountClaimed`,range:`decimal`,definition:`What the claimant is asking for.`,comment:`The ask, which the assessment may not agree with.`,example:`3200.00`},{name:`claimStatus`,range:`string`,definition:`Where the claim has got to.`,comment:`Text, as with policy status, and with the same reservation.`,example:`Under assessment`},{name:`description`,range:`string`,definition:`What happened, in the claimant own words.`,comment:`Free prose, and often the only account of the incident there is.`,example:`A tile came off the roof in high wind and cracked the conservatory.`}]},{name:`ClaimAssessment`,at:[1560,700],definition:`The judgement the firm reached on a claim.`,comment:`Separate from the claim so that what was asked and what was decided are never confused, and so an assessor can be recorded.`,example:`Approved at £2,950.`,attributes:[{name:`assessedOn`,range:`date`,definition:`The day the judgement was made.`,comment:`What service-level targets are measured against.`,example:`2024-08-29`},{name:`amountApproved`,range:`decimal`,definition:`What the firm agreed to pay.`,comment:`Frequently less than the amount claimed, which is the point of holding both.`,example:`2950.00`},{name:`isFraudSuspected`,range:`boolean`,definition:`Whether the claim was referred as suspicious.`,comment:`A referral, not a finding, and the distinction is worth keeping.`,example:`false`},{name:`assessorNotes`,range:`string`,definition:`What the assessor recorded about the decision.`,comment:`Internal prose, which is why it is not on the claim itself.`,example:`Damage consistent with the reported wind speeds. Settled at trade rates.`}]},{name:`Payment`,at:[1840,700],definition:`Money moving in either direction.`,comment:`One class for premium and settlement both, which is why it points at a Party rather than a claimant.`,example:`A settlement of £2,950.`,attributes:[{name:`paidOn`,range:`date`,definition:`The day the money moved.`,comment:`When it left, not when it was authorised.`,example:`2024-09-02`},{name:`amount`,range:`decimal`,definition:`How much was paid.`,comment:`Always positive; direction is a matter of who it went to.`,example:`2950.00`},{name:`currency`,range:`string`,definition:`What currency the payment was made in.`,comment:`Stated here and nowhere else, which is an inconsistency worth noticing: every other amount in this schema assumes one.`,example:`GBP`},{name:`method`,range:`string`,definition:`How the money was sent.`,comment:`Text, so a new payment rail needs no schema change.`,example:`Bank transfer`}]}],relations:[{name:`heldBy`,from:`Policy`,to:`Party`,definition:`The party the policy belongs to.`,comment:`Points at Party, not at Person, which is exactly what the abstraction buys: one relation covers a policy held by an individual and one held by a company.`,example:`Policy MP-4471 is heldBy Joy Okafor.`},{name:`soldBy`,from:`Policy`,to:`Agent`,definition:`The agent who sold the policy.`,comment:`Who earns the commission, which is why it is the agent and not the firm.`,example:`Policy MP-4471 was soldBy agent AG-2210.`},{name:`providesCoverage`,from:`Policy`,to:`Coverage`,definition:`A risk this policy covers.`,comment:`Several per policy, each with its own limit — the reason Coverage is a class.`,example:`Policy MP-4471 providesCoverage theft up to £10,000.`},{name:`coversAsset`,from:`Coverage`,to:`InsuredAsset`,definition:`The asset this cover applies to.`,comment:`From the coverage rather than the policy, so one policy can cover several things.`,example:`The theft cover coversAsset the panel van.`},{name:`insures`,from:`MotorPolicy`,to:`Vehicle`,definition:`The asset this policy protects.`,comment:`The clearest case in the library of one property meaning something different per class. Drawn to Vehicle from a motor policy and to Dwelling from a home policy, so RDFS states no range at all — a union would wrongly permit a motor policy to insure a house. The SHACL shapes keep them apart; compare the two in the Export tab.`,example:`Policy MP-4471 insures the panel van.`},{name:`insures`,from:`HomePolicy`,to:`Dwelling`},{name:`beneficiary`,from:`LifePolicy`,to:`Person`,definition:`Who is paid when a life policy pays out.`,comment:`A Person rather than a Party, because a life policy pays a named individual.`,example:`A life policy has beneficiary Joy Okafor.`},{name:`madeAgainst`,from:`Claim`,to:`Policy`,definition:`The policy this claim is made under.`,comment:`What decides whether cover was in force on the incident date.`,example:`Claim CL-2024-8812 was madeAgainst policy MP-4471.`},{name:`claimedBy`,from:`Claim`,to:`Party`,definition:`Who made the claim.`,comment:`Not always the policyholder, which is why it is recorded separately from heldBy.`,example:`Claim CL-2024-8812 was claimedBy Joy Okafor.`},{name:`assesses`,from:`ClaimAssessment`,to:`Claim`,definition:`The claim this judgement is about.`,comment:`One assessment per claim here; a reopened claim would need more than one.`,example:`The August assessment assesses claim CL-2024-8812.`},{name:`assessedBy`,from:`ClaimAssessment`,to:`Person`,definition:`Who reached the judgement.`,comment:`A Person, so an external loss adjuster fits without being an employee.`,example:`The August assessment was assessedBy Joy Okafor.`},{name:`settles`,from:`Payment`,to:`Claim`,definition:`The claim this payment discharges.`,comment:`Absent on a premium payment, which is money moving the other way.`,example:`A £2,950 payment settles claim CL-2024-8812.`},{name:`paidTo`,from:`Payment`,to:`Party`,definition:`Who received the money.`,comment:`A Party, so a payment to a repairer and one to a policyholder look the same.`,example:`The £2,950 payment was paidTo Joy Okafor.`},{name:`ownedBy`,from:`InsuredAsset`,to:`Party`,definition:`Who owns the insured asset.`,comment:`Kept apart from who holds the policy, because a company can insure a vehicle its director owns.`,example:`The panel van is ownedBy Mill Lane Joinery Limited.`}],spareProperties:[{name:`replacesPolicy`,definition:`A policy this one supersedes on renewal.`,comment:`Declared but never drawn, so it sits unused in the property list. Draw it between two classes to put it on the canvas.`,example:`Policy MP-4471 replacesPolicy MP-3980.`}]}),h=[u({key:`music`,title:`Music library`,summary:`Artists, releases, tracks and gigs. The gentlest place to start — everyone already knows this domain, so the modelling is all that is new.`,iri:`https://example.org/music/`,prefix:`mus`,metadata:[[`dcterms:title`,`Music Catalogue`,`en`],[`dcterms:description`,`A schema covering recorded music, the people who make it and the places it is played.`,`en`],[`dcterms:creator`,`OntoSchema examples`],[`owl:versionInfo`,`1.0.0`]],classes:[{name:`Artist`,at:[40,40],definition:`Anyone credited with making music, whether one person or a group.`,comment:`Deliberately above the split between a solo performer and a band, so a credit can point here without deciding which it is.`,example:`Miles Davis, or Fleetwood Mac.`,labels:[[`Artist`,`en`],[`Artiest`,`nl`]],attributes:[{name:`artistName`,range:`string`,definition:`The name the artist releases music under.`,comment:`The performing name, which for a solo artist need not be their legal one.`,example:`Nina Simone`},{name:`formedIn`,range:`integer`,definition:`The year the artist began releasing or performing.`,comment:`A year rather than a date: the month a band formed is rarely agreed on.`,example:`1967`},{name:`countryOfOrigin`,range:`string`,definition:`Where the artist started out.`,comment:`Where they began, not where they live now, so a discography stays sorted the way listeners expect.`,example:`Nigeria`},{name:`isActive`,range:`boolean`,definition:`Whether the artist is still recording or performing.`,comment:`Says nothing about why they stopped; a hiatus and a breakup look the same.`,example:`false`},{name:`website`,range:`anyURI`,definition:`The official site for the artist.`,comment:`One address, the one the artist controls, not every page that mentions them.`,example:`https://example.org/artists/nina-simone`}]},{name:`SoloArtist`,parent:`Artist`,at:[40,360],definition:`One person performing under their own name or a stage name.`,comment:`A solo artist may also be a member of a band; the two are not exclusive, which is why membership is a relation rather than a subclass.`,example:`Nina Simone, recording alone.`,attributes:[{name:`realName`,range:`string`,definition:`The name the performer was born with.`,comment:`Held apart from the performing name so both can be searched.`,example:`Eunice Kathleen Waymon`},{name:`dateOfBirth`,range:`date`,definition:`The day the performer was born.`,comment:`A full date here, unlike a band, because a birthday is a matter of record.`,example:`1933-02-21`},{name:`mainInstrument`,range:`string`,definition:`The instrument the performer is best known for.`,comment:`One instrument, the signature one; the rest belong in a fuller model.`,example:`Piano`}]},{name:`Band`,parent:`Artist`,at:[320,360],definition:`A group of musicians performing together under one name.`,comment:`The band is the artist, not the people in it: a line-up change leaves the credit intact.`,example:`Fleetwood Mac.`,attributes:[{name:`memberCount`,range:`integer`,definition:`How many musicians are in the current line-up.`,comment:`A convenience for display. The line-up itself is held by hasMember, which is the version that can be queried.`,example:`5`},{name:`disbandedIn`,range:`integer`,definition:`The year the band stopped performing together.`,comment:`Absent while the band is active, which is what isActive on Artist reports.`,example:`1995`}]},{name:`Musician`,at:[320,660],definition:`A person who plays in a band.`,comment:`Not a subclass of Artist: someone can play in a band for years without ever being credited as one.`,example:`The drummer on a 1973 tour.`,attributes:[{name:`fullName`,range:`string`,definition:`The musician's full personal name.`,comment:`A person, so no stage name here — that belongs to whoever they record as.`,example:`Christine McVie`},{name:`instrument`,range:`string`,definition:`What the musician plays in this band.`,comment:`What they play here, which may not be what they are known for elsewhere.`,example:`Keyboards`},{name:`joinedOn`,range:`date`,definition:`The day the musician joined the band.`,comment:`On the musician rather than on the membership, which is the simplification this example accepts: a member who leaves and returns keeps one date.`,example:`1970-08-01`}]},{name:`Release`,at:[660,40],definition:`A published body of recorded music, issued as one thing.`,comment:`The published object, not the recording session: the same tracks reissued later are a second release.`,example:`Kind of Blue, Columbia, 1959.`,attributes:[{name:`releaseTitle`,range:`string`,definition:`The title the release was published under.`,comment:`Named apart from a track title, which a release may happen to share.`,example:`Kind of Blue`},{name:`releasedOn`,range:`date`,definition:`The day the release first went on sale.`,comment:`The first issue. A remaster gets its own release rather than a second date.`,example:`1959-08-17`},{name:`catalogueNumber`,range:`string`,definition:`The label's own identifier for this release.`,comment:`A string, not a number: catalogue numbers carry letters and punctuation.`,example:`CL 1355`},{name:`trackCount`,range:`integer`,definition:`How many tracks the release contains.`,comment:`Redundant against appearsOn, and kept because a listing shows it everywhere.`,example:`5`},{name:`isRemastered`,range:`boolean`,definition:`Whether this issue has been remastered from the original tapes.`,comment:`A property of this issue, which is why a remaster is a release of its own.`,example:`true`}]},{name:`Album`,parent:`Release`,at:[660,360],definition:`A full-length release, long enough to stand as a body of work.`,comment:`The line between an album and a single is one of length and intent, and every label draws it differently.`,example:`Kind of Blue.`,attributes:[{name:`isDoubleAlbum`,range:`boolean`,definition:`Whether the album was issued across two discs.`,comment:`A fact about the physical issue, which survives into how a CD is reissued.`,example:`true`}]},{name:`Single`,parent:`Release`,at:[940,360],definition:`A short release built around one track.`,comment:`Still a release, so it carries a catalogue number and a label like any other; leadTrack is what makes it a single.`,example:`Go Your Own Way, 1976.`,attributes:[{name:`chartPeak`,range:`integer`,definition:`The highest chart position the single reached.`,comment:`Which chart is left out, which is the simplification: a real catalogue needs one figure per territory.`,example:`10`}]},{name:`Track`,at:[1280,40],definition:`One recorded piece of music.`,comment:`Belongs to a release rather than to an artist, so the same recording appearing on a compilation is one track on two releases.`,example:`So What.`,attributes:[{name:`trackTitle`,range:`string`,definition:`The name of the recording.`,comment:`Named apart from the release title, which it can legitimately duplicate.`,example:`So What`},{name:`trackNumber`,range:`integer`,definition:`Where the track sits in the running order.`,comment:`Position on the release, so a track on two releases has two numbers — the reason a fuller model would put this on appearsOn.`,example:`1`},{name:`durationSeconds`,range:`integer`,definition:`How long the recording runs, in seconds.`,comment:`Seconds rather than a formatted string, so durations can be added and compared.`,example:`562`},{name:`isExplicit`,range:`boolean`,definition:`Whether the recording carries an explicit-content warning.`,comment:`The advisory as issued, not a judgement about the lyrics.`,example:`false`},{name:`isrc`,range:`string`,label:`ISRC`,definition:`The International Standard Recording Code identifying this recording.`,comment:`Identifies the recording itself, so it follows the track onto every release it appears on.`,example:`USSM15900001`},{name:`bpm`,range:`integer`,label:`BPM`,definition:`The tempo of the recording in beats per minute.`,comment:`One figure for the whole track, which a piece that changes tempo will defeat.`,example:`136`}]},{name:`Genre`,at:[1280,360],definition:`A style of music that releases can be grouped by.`,comment:`Attached to the release rather than the track, because a release is what gets shelved under a genre.`,example:`Modal jazz.`,attributes:[{name:`genreName`,range:`string`,definition:`What the style is called.`,comment:`The common name; genres have no authority to defer to.`,example:`Modal jazz`},{name:`originatedIn`,range:`integer`,definition:`The year the style is generally held to have emerged.`,comment:`Approximate by nature, which is why it is a year and not a date.`,example:`1958`}]},{name:`RecordLabel`,at:[660,660],definition:`A company that publishes releases.`,comment:`The publisher, kept separate from the artist so a catalogue can be browsed either way.`,example:`Columbia Records.`,attributes:[{name:`labelName`,range:`string`,definition:`The name the label trades under.`,comment:`The imprint, which may differ from the company that owns it.`,example:`Columbia Records`},{name:`foundedIn`,range:`integer`,definition:`The year the label was founded.`,comment:`The founding year of the imprint, not of any parent company.`,example:`1887`},{name:`headquarters`,range:`string`,definition:`The city the label operates from.`,comment:`A city, not a full address: this is for grouping, not for post.`,example:`New York`}]},{name:`Concert`,at:[1600,40],definition:`A live performance given on a particular date at a particular place.`,comment:`One performance, not a tour: a tour is the set of concerts, which this example leaves out.`,example:`The Newport Jazz Festival set, 17 July 1958.`,attributes:[{name:`performedOn`,range:`dateTime`,definition:`When the performance began.`,comment:`A time as well as a date, because two sets in one day are two concerts.`,example:`1958-07-17T20:30:00`},{name:`ticketPrice`,range:`decimal`,definition:`What a standard ticket cost.`,comment:`Decimal rather than float, so money is not rounded; the currency is left out, which a real model would need.`,example:`42.50`},{name:`attendance`,range:`integer`,definition:`How many people came.`,comment:`Counted at the door, so it can fall short of the capacity of the venue.`,example:`1800`},{name:`isSoldOut`,range:`boolean`,definition:`Whether every ticket was sold.`,comment:`Recorded rather than derived: a concert can sell out and still have empty seats.`,example:`true`}]},{name:`Venue`,at:[1600,360],definition:`A place where concerts are held.`,comment:`The place, which outlives any one concert and usually any one artist.`,example:`Freebody Park, Newport.`,attributes:[{name:`venueName`,range:`string`,definition:`What the venue is called.`,comment:`The current name; venues are renamed often, and only the latest is kept here.`,example:`Freebody Park`},{name:`city`,range:`string`,definition:`The town or city the venue is in.`,comment:`A city rather than a full address, which is what listings are grouped by.`,example:`Newport`},{name:`capacity`,range:`integer`,definition:`The largest audience the venue can hold.`,comment:`The licensed figure, which a standing configuration can exceed on paper.`,example:`5000`},{name:`isOutdoor`,range:`boolean`,definition:`Whether performances are in the open air.`,comment:`Worth its own field because it is what makes a date weather-dependent.`,example:`true`}]},{name:`Playlist`,at:[1280,660],definition:`An ordered selection of tracks put together by a listener.`,comment:`Points at tracks rather than releases, which is what separates it from a compilation album.`,example:`Late night listening.`,attributes:[{name:`playlistName`,range:`string`,definition:`What the listener called it.`,comment:`Free text with no authority behind it, unlike a release title.`,example:`Late night listening`},{name:`createdOn`,range:`date`,definition:`The day the playlist was made.`,comment:`When it was created, not when it was last changed.`,example:`2024-03-11`},{name:`isPublic`,range:`boolean`,definition:`Whether anyone can see the playlist.`,comment:`Visibility only. Who may edit it is a separate question this model skips.`,example:`true`}]}],relations:[{name:`performedBy`,from:`Track`,to:`Artist`,definition:`The artist who performed this recording or this concert.`,comment:`Drawn from both Track and Concert, so one property covers the studio and the stage. That is why it carries no single rdfs:domain in the export.`,example:`So What is performedBy Miles Davis.`},{name:`performedBy`,from:`Concert`,to:`Artist`},{name:`appearsOn`,from:`Track`,to:`Release`,definition:`The release this track was published on.`,comment:`Many to many on purpose: a recording that appears on an album and a compilation is one track, drawn twice.`,example:`So What appearsOn Kind of Blue.`},{name:`releasedBy`,from:`Release`,to:`Artist`,definition:`The artist the release is credited to.`,comment:`The credit on the sleeve, which is not always everyone who played on it.`,example:`Kind of Blue is releasedBy Miles Davis.`},{name:`publishedBy`,from:`Release`,to:`RecordLabel`,definition:`The label that issued the release.`,comment:`The label for this issue; a reissue on another label is a separate release.`,example:`Kind of Blue is publishedBy Columbia Records.`},{name:`hasGenre`,from:`Release`,to:`Genre`,definition:`A style this release is filed under.`,comment:`More than one is expected, and none of them is the primary genre.`,example:`Kind of Blue hasGenre Modal jazz.`},{name:`hasMember`,from:`Band`,to:`Musician`,definition:`A musician who plays in this band.`,comment:`Current and former members both, which is why Musician carries the date they joined.`,example:`Fleetwood Mac hasMember Christine McVie.`},{name:`heldAt`,from:`Concert`,to:`Venue`,definition:`Where the concert took place.`,comment:`One venue per concert; a show that moves halfway through is two concerts.`,example:`The 1958 set was heldAt Freebody Park.`},{name:`includesTrack`,from:`Playlist`,to:`Track`,definition:`A track the playlist contains.`,comment:`The order the listener chose is not captured here, which is the honest limit of a plain relation.`,example:`Late night listening includesTrack So What.`},{name:`coverOf`,from:`Track`,to:`Track`,definition:`An earlier recording that this one reinterprets.`,comment:`From a class to itself, which is legal and common. It points one way: a cover knows its original, and the original knows nothing.`,example:`All Along the Watchtower (1968) is a coverOf All Along the Watchtower (1967).`},{name:`influencedBy`,from:`Artist`,to:`Artist`,definition:`An artist whose work shaped this one.`,comment:`A claim rather than a fact, and the reason this example keeps it deliberately vague.`,example:`Herbie Hancock is influencedBy Miles Davis.`},{name:`leadTrack`,from:`Single`,to:`Track`,definition:`The track the single was built around.`,comment:`What makes a single a single, as against a short album.`,example:`Go Your Own Way has leadTrack Go Your Own Way.`}]}),u({key:`recipes`,title:`Recipes and cooking`,summary:`Recipes, what goes into them and who cooks them. Teaches the most common modelling lesson there is: when a link needs its own facts, it needs its own class.`,iri:`https://example.org/cooking/`,prefix:`cook`,metadata:[[`dcterms:title`,`Recipe Collection`,`en`],[`dcterms:description`,`A schema covering recipes, ingredients, quantities, methods and the people who cook them.`,`en`],[`dcterms:creator`,`OntoSchema examples`],[`owl:versionInfo`,`1.0.0`]],classes:[{name:`Recipe`,at:[40,40],definition:`Instructions for making one dish, with its ingredients and its method.`,comment:`The written recipe, not an occasion of cooking it: what someone thought of the result belongs on Review.`,example:`Tarte tatin.`,labels:[[`Recipe`,`en`],[`Recept`,`nl`],[`Rezept`,`de`]],attributes:[{name:`recipeTitle`,range:`string`,definition:`The name the dish is published under.`,comment:`The name as written; the same dish under two names is two recipes here.`,example:`Tarte tatin`},{name:`servings`,range:`integer`,definition:`How many people the quantities are written for.`,comment:`What every quantity on RecipeIngredient is relative to, so it cannot be absent.`,example:`6`},{name:`prepMinutes`,range:`integer`,definition:`Hands-on time before cooking begins.`,comment:`Kept apart from cooking time because only one of the two needs attention.`,example:`25`},{name:`cookMinutes`,range:`integer`,definition:`Time the dish spends cooking.`,comment:`Total across the method, which the per-step durations should add up to.`,example:`45`},{name:`difficulty`,range:`string`,definition:`Roughly how demanding the recipe is.`,comment:`A string because there is no agreed scale; a real collection would make this a class.`,example:`Moderate`},{name:`isVegetarian`,range:`boolean`,definition:`Whether the recipe contains no meat or fish.`,comment:`Recorded rather than worked out from the ingredients, because stock and rennet defeat the obvious calculation.`,example:`true`},{name:`isVegan`,range:`boolean`,definition:`Whether the recipe contains no animal products at all.`,comment:`Stricter than isVegetarian, and never true where that one is false.`,example:`false`},{name:`publishedOn`,range:`date`,definition:`The day the recipe was published.`,comment:`First publication, so a revised recipe keeps the original date.`,example:`2023-09-14`},{name:`sourceUrl`,range:`anyURI`,label:`Source URL`,definition:`Where the recipe was published or adapted from.`,comment:`Credit for an adaptation, which is why it is a URL and not a citation.`,example:`https://example.org/recipes/tarte-tatin`}]},{name:`RecipeIngredient`,at:[400,40],definition:`One ingredient as used in one recipe, together with how much of it that recipe needs.`,comment:`The lesson of this example. A quantity belongs to neither the recipe nor the ingredient alone, so the pairing gets a class of its own — the move to reach for whenever a link needs facts attached to it.`,example:`200g of plain flour, sifted, in the tarte tatin.`,attributes:[{name:`quantity`,range:`decimal`,definition:`How much of the ingredient is needed.`,comment:`Decimal because half an onion is a real amount; the unit is held beside it.`,example:`200`},{name:`unit`,range:`string`,definition:`What the quantity is measured in.`,comment:`A string here, which is the compromise: a serious model would use a units vocabulary so amounts could be converted.`,example:`g`},{name:`preparationNote`,range:`string`,definition:`What to do to the ingredient before it goes in.`,comment:`Belongs to this use of the ingredient, not to the ingredient — flour is not inherently sifted.`,example:`sifted`},{name:`isOptional`,range:`boolean`,definition:`Whether the dish works without this ingredient.`,comment:`A property of the line rather than of the ingredient, which may be essential elsewhere.`,example:`true`}]},{name:`Ingredient`,at:[760,40],definition:`A foodstuff, described independently of any recipe that uses it.`,comment:`Holds only what is true of the ingredient everywhere. Anything that varies by recipe lives on RecipeIngredient.`,example:`Plain flour.`,labels:[[`Ingredient`,`en`],[`Ingrediënt`,`nl`]],attributes:[{name:`ingredientName`,range:`string`,definition:`What the foodstuff is called.`,comment:`The common name, which is why the same thing appears twice across regions.`,example:`Plain flour`},{name:`caloriesPer100g`,range:`integer`,label:`Calories per 100g`,definition:`Energy in one hundred grams of the ingredient.`,comment:`Per fixed weight so ingredients can be compared and a dish totalled.`,example:`364`},{name:`isAllergen`,range:`boolean`,definition:`Whether the ingredient is a common allergen.`,comment:`A blunt flag. Which allergy it triggers is what DietaryRestriction is for.`,example:`true`},{name:`storageAdvice`,range:`string`,definition:`How the ingredient should be kept.`,comment:`Free text, because the useful version of this is a sentence, not a category.`,example:`Airtight, away from light.`}]},{name:`IngredientCategory`,at:[1100,40],definition:`A grouping of ingredients such as dairy, pulses or spices.`,comment:`Flat on purpose: nesting categories is a hierarchy this example does not need.`,example:`Dairy.`,attributes:[{name:`categoryName`,range:`string`,definition:`What the grouping is called.`,comment:`The shelf label, roughly — how a shop or a cupboard is organised.`,example:`Dairy`},{name:`isPerishable`,range:`boolean`,definition:`Whether things in this category spoil quickly.`,comment:`On the category rather than the ingredient, which is a deliberate simplification.`,example:`true`}]},{name:`Step`,at:[40,380],definition:`One instruction in the method of a recipe.`,comment:`Ordered by its own number rather than by the relation, which carries no order.`,example:`Caramelise the sugar in the pan.`,attributes:[{name:`stepNumber`,range:`integer`,definition:`Where this instruction comes in the method.`,comment:`The order lives here because hasStep is a plain relation and has none.`,example:`3`},{name:`instruction`,range:`string`,definition:`The action to carry out at this point in the method.`,comment:`One action per step; a step doing three things should have been three.`,example:`Caramelise the sugar until it is the colour of a copper coin.`},{name:`durationMinutes`,range:`integer`,definition:`How long this step takes.`,comment:`Should sum roughly to the cooking time on the recipe, though nothing enforces it.`,example:`8`},{name:`temperatureCelsius`,range:`integer`,definition:`The temperature this step calls for.`,comment:`Celsius by convention, so a temperature carries no unit of its own.`,example:`180`}]},{name:`Equipment`,at:[400,380],definition:`A tool or appliance that a step calls for.`,comment:`Attached to the step rather than the recipe, so the equipment list can be worked out from the method.`,example:`A heavy ovenproof frying pan.`,attributes:[{name:`equipmentName`,range:`string`,definition:`What the tool is called.`,comment:`The everyday name, not a manufacturer or a model.`,example:`Ovenproof frying pan`},{name:`isEssential`,range:`boolean`,definition:`Whether the step can be done without it.`,comment:`What separates equipment you must buy from equipment you can improvise.`,example:`true`}]},{name:`Cuisine`,at:[760,380],definition:`A regional cooking tradition.`,comment:`A tradition rather than a country: the two rarely line up neatly.`,example:`French.`,attributes:[{name:`cuisineName`,range:`string`,definition:`What the tradition is called.`,comment:`The name in common use, which is usually an adjective.`,example:`French`},{name:`region`,range:`string`,definition:`Where the tradition comes from.`,comment:`Broader or narrower than a country, which is why it is not one.`,example:`Western Europe`}]},{name:`Course`,at:[1100,380],definition:`Where a dish falls in a meal: starter, main or dessert.`,comment:`A small closed set in practice, kept as a class so a collection can add to it.`,example:`Dessert.`,attributes:[{name:`courseName`,range:`string`,definition:`What the course is called.`,comment:`The name used at the table.`,example:`Dessert`},{name:`servingOrder`,range:`integer`,definition:`Where the course comes in a meal.`,comment:`What lets courses be sorted without hard-coding the names.`,example:`3`}]},{name:`Cook`,at:[40,700],definition:`Someone who writes recipes or follows them.`,comment:`One class for both authors and reviewers, because the same person is usually both.`,example:`A home cook publishing to the collection.`,attributes:[{name:`cookName`,range:`string`,definition:`What the cook goes by.`,comment:`A display name, which need not be a legal one.`,example:`Delphine Roux`},{name:`skillLevel`,range:`string`,definition:`How experienced the cook is.`,comment:`Self-declared, and matched loosely against recipe difficulty.`,example:`Confident`},{name:`joinedOn`,range:`date`,definition:`The day the cook joined the collection.`,comment:`Membership of this collection, not when they learned to cook.`,example:`2022-01-30`}]},{name:`ProfessionalChef`,parent:`Cook`,at:[40,1e3],definition:`A cook who does it for a living.`,comment:`A subclass rather than a flag on Cook, because it brings facts of its own that make no sense on a home cook.`,example:`The head chef of a restaurant.`,attributes:[{name:`restaurantName`,range:`string`,definition:`Where the chef currently cooks.`,comment:`One kitchen, the current one; a career history is out of scope.`,example:`La Chèvre`},{name:`michelinStars`,range:`integer`,definition:`Stars currently held by the restaurant.`,comment:`Held by the restaurant rather than the chef, and kept here only because that is how it is spoken about.`,example:`2`}]},{name:`Review`,at:[400,700],definition:`What someone thought of a recipe after cooking it.`,comment:`A class rather than a rating on the recipe, because it needs an author and a date of its own.`,example:`Four stars, would make again.`,attributes:[{name:`rating`,range:`integer`,definition:`The score given, out of five.`,comment:`A whole number: half stars are a display convention, not a stored value.`,example:`4`},{name:`comment`,range:`string`,definition:`What the reviewer wrote.`,comment:`Free prose, and the part that is actually read.`,example:`Needed ten minutes longer than stated, otherwise perfect.`},{name:`reviewedOn`,range:`date`,definition:`The day the review was written.`,comment:`When it was written, which can be well after the cooking.`,example:`2024-02-02`},{name:`wouldCookAgain`,range:`boolean`,definition:`Whether the reviewer would make it a second time.`,comment:`Often more telling than the score, which is why it is asked separately.`,example:`true`}]},{name:`DietaryRestriction`,at:[760,700],definition:`Something a diner cannot or will not eat.`,comment:`Covers both medical need and choice, which is why isMedical exists rather than two classes.`,example:`Coeliac disease.`,attributes:[{name:`restrictionName`,range:`string`,definition:`What the restriction is called.`,comment:`Named as a diner would say it, not as a clinician would.`,example:`Gluten-free`},{name:`isMedical`,range:`boolean`,definition:`Whether the restriction is a medical requirement.`,comment:`The difference between a preference and an allergy, which changes how it is treated.`,example:`true`}]},{name:`MealPlan`,at:[1100,700],definition:`Recipes chosen to be cooked over a period.`,comment:`Which recipe falls on which day is not held here, which is its honest limit.`,example:`A week of weeknight dinners.`,attributes:[{name:`planName`,range:`string`,definition:`What the plan is called.`,comment:`Free text chosen by whoever made the plan.`,example:`Weeknight dinners`},{name:`startsOn`,range:`date`,definition:`The first day of the plan.`,comment:`With dayCount, this is what fixes the period the plan covers.`,example:`2024-04-08`},{name:`dayCount`,range:`integer`,definition:`How many days the plan runs for.`,comment:`A length rather than an end date, because plans are described that way.`,example:`7`}]}],relations:[{name:`usesIngredient`,from:`Recipe`,to:`RecipeIngredient`,definition:`An ingredient line belonging to this recipe.`,comment:`Points at the pairing, not at the ingredient, which is what carries the amount. The step everyone skips first time.`,example:`Tarte tatin usesIngredient the 200g flour line.`},{name:`refersTo`,from:`RecipeIngredient`,to:`Ingredient`,definition:`The foodstuff this ingredient line is about.`,comment:`The other half of the pairing, which is what makes the amount mean anything.`,example:`The 200g flour line refersTo Plain flour.`},{name:`inCategory`,from:`Ingredient`,to:`IngredientCategory`,definition:`The grouping this ingredient belongs to.`,comment:`One category per ingredient here, which real shelving would not respect.`,example:`Butter is inCategory Dairy.`},{name:`hasStep`,from:`Recipe`,to:`Step`,definition:`An instruction in this recipe method.`,comment:`Carries no order of its own, which is why Step numbers itself.`,example:`Tarte tatin hasStep "Caramelise the sugar".`},{name:`requiresEquipment`,from:`Step`,to:`Equipment`,definition:`A tool this step needs.`,comment:`On the step rather than the recipe, so the equipment list follows from the method.`,example:`The caramel step requiresEquipment an ovenproof frying pan.`},{name:`fromCuisine`,from:`Recipe`,to:`Cuisine`,definition:`The cooking tradition this recipe belongs to.`,comment:`A single tradition, which a fusion dish will happily contradict.`,example:`Tarte tatin is fromCuisine French.`},{name:`servedAs`,from:`Recipe`,to:`Course`,definition:`Where in a meal the dish is served.`,comment:`More than one is normal: plenty of dishes work as a starter or a main.`,example:`Tarte tatin is servedAs Dessert.`},{name:`createdBy`,from:`Recipe`,to:`Cook`,definition:`The cook who wrote this recipe.`,comment:`Authorship of the written recipe, not of the dish itself.`,example:`Tarte tatin createdBy Delphine Roux.`},{name:`reviews`,from:`Review`,to:`Recipe`,definition:`The recipe this review is about.`,comment:`From the review outward, so a recipe need not know how many it has.`,example:`A four-star review reviews Tarte tatin.`},{name:`writtenBy`,from:`Review`,to:`Cook`,definition:`The cook who wrote this review.`,comment:`The same Cook class as authorship, because the same people do both.`,example:`The four-star review is writtenBy Delphine Roux.`},{name:`incompatibleWith`,from:`DietaryRestriction`,to:`Ingredient`,definition:`Something this restriction rules out.`,comment:`Drawn from a restriction to both an ingredient and a whole recipe, so one property covers both. That is why it has no single rdfs:range in the export.`,example:`Gluten-free is incompatibleWith Plain flour.`},{name:`incompatibleWith`,from:`DietaryRestriction`,to:`Recipe`},{name:`includesRecipe`,from:`MealPlan`,to:`Recipe`,definition:`A recipe chosen for this plan.`,comment:`Which day it falls on is not captured, which a working meal planner would need.`,example:`Weeknight dinners includesRecipe Tarte tatin.`},{name:`variantOf`,from:`Recipe`,to:`Recipe`,definition:`A recipe this one is an adaptation of.`,comment:`From a class to itself, and one-way: the variant knows its original, and the original is unchanged by it.`,example:`A pear tarte tatin is a variantOf the apple one.`}],spareProperties:[{name:`substituteFor`,definition:`An ingredient that can stand in for another.`,comment:`Declared but never drawn, so it sits unused in the property list — which is the quickest way to see what an unused property looks like.`,example:`Margarine is a substituteFor butter.`}]}),f,p,m];export{h as EXAMPLES,d as exampleSize};